import{_ as n,c as s,a,o as i}from"./app-CsuCb6I7.js";const l={};function d(r,e){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="الحلقات-تكرار-المهام-تلقائيًا" tabindex="-1"><a class="header-anchor" href="#الحلقات-تكرار-المهام-تلقائيًا"><span>الحلقات: تكرار المهام تلقائيًا</span></a></h1><h2 id="لماذا-نحتاج-إلى-الحلقات؟" tabindex="-1"><a class="header-anchor" href="#لماذا-نحتاج-إلى-الحلقات؟"><span>لماذا نحتاج إلى الحلقات؟</span></a></h2><p>تخيل أن يُطلب منك كتابة العبارة &quot;لن أتحدث في الفصل&quot; على السبورة 100 مرة. سيستغرق ذلك وقتًا طويلاً وستؤلمك يدك!</p><p>في البرمجة، نحن نكره القيام بنفس الشيء مرارًا وتكرارًا بشكل يدوي. كلما دعت الحاجة إلى تكرار عملية ما، نستخدم أداة تسمى <strong>الحلقة (Loop)</strong>.</p><p>الحلقة هي ببساطة مجموعة من التعليمات التي يكررها الكمبيوتر تلقائيًا حتى يتم استيفاء شرط توقف محدد. تجعل الحلقات خوارزمياتنا فعالة وتوفر علينا الكثير من الكتابة!</p><h2 id="حلقة-for" tabindex="-1"><a class="header-anchor" href="#حلقة-for"><span>حلقة <code>FOR</code></span></a></h2><p>إحدى أكثر الطرق شيوعًا لجعل الكمبيوتر يكرر مهمة ما هي استخدام <strong>حلقة FOR</strong>. تُعد حلقة FOR مثالية عندما تعرف بالضبط <em>كم عدد المرات</em> التي تريد تكرار شيء ما فيها.</p><p>إليك كيف يبدو التركيب في الكود الزائف:</p><div class="language-pseudo line-numbers-mode" data-highlighter="prismjs" data-ext="pseudo"><pre><code><span class="line">FOR counter FROM 1 TO 4 DO</span>
<span class="line">  PRINT counter</span>
<span class="line">END FOR</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>إذا قمت بتشغيل هذه الخوارزمية، سيطبع الكمبيوتر:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">1</span>
<span class="line">2</span>
<span class="line">3</span>
<span class="line">4</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="تفصيل-حلقة-for" tabindex="-1"><a class="header-anchor" href="#تفصيل-حلقة-for"><span>تفصيل حلقة <code>FOR</code></span></a></h3><p>دعونا نلقي نظرة فاحصة على كيفية عملها:</p><ol><li><code>FOR counter FROM 1</code>: نقوم بإنشاء متغير مؤقت يسمى <code>counter</code> (العداد) ونبدأ من الرقم 1.</li><li><code>TO 4</code>: نخبر الحلقة بالاستمرار في التكرار حتى يصل العداد إلى 4.</li><li><code>DO</code>: هذا يخبر الكمبيوتر بتنفيذ التعليمات الموجودة داخل الحلقة.</li><li>بعد كل تكرار، يقوم الكمبيوتر تلقائيًا بزيادة العداد بمقدار 1.</li><li><code>END FOR</code>: هذا يمثل نهاية كتلة الحلقة.</li></ol><h3 id="مثال-من-العالم-الواقعي" tabindex="-1"><a class="header-anchor" href="#مثال-من-العالم-الواقعي"><span>مثال من العالم الواقعي</span></a></h3><p>دعنا نستخدم حلقة <code>FOR</code> للعد التنازلي للأيام حتى عطلة نهاية الأسبوع:</p><div class="language-pseudo line-numbers-mode" data-highlighter="prismjs" data-ext="pseudo"><pre><code><span class="line">FOR day FROM 1 TO 5 DO</span>
<span class="line">  PRINT &quot;It is day &quot; + day + &quot; of the work week.&quot;</span>
<span class="line">END FOR</span>
<span class="line"></span>
<span class="line">PRINT &quot;Hooray! It is the weekend!&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>سيكون الناتج:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">It is day 1 of the work week.</span>
<span class="line">It is day 2 of the work week.</span>
<span class="line">It is day 3 of the work week.</span>
<span class="line">It is day 4 of the work week.</span>
<span class="line">It is day 5 of the work week.</span>
<span class="line">Hooray! It is the weekend!</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="حلقة-while" tabindex="-1"><a class="header-anchor" href="#حلقة-while"><span>حلقة <code>WHILE</code></span></a></h2><p>أحيانًا، لا تعرف بالضبط عدد المرات التي تحتاج فيها الحلقة للعمل. أنت فقط تريدها أن تستمر <strong>طالما أن</strong> (While) شرطًا معينًا صحيح. لهذا الغرض، نستخدم <strong>حلقة WHILE</strong>.</p><div class="language-pseudo line-numbers-mode" data-highlighter="prismjs" data-ext="pseudo"><pre><code><span class="line">SET hunger_level TO 5</span>
<span class="line"></span>
<span class="line">WHILE hunger_level &gt; 0 DO</span>
<span class="line">  PRINT &quot;Eating a slice of pizza...&quot;</span>
<span class="line">  SET hunger_level TO hunger_level - 1</span>
<span class="line">END WHILE</span>
<span class="line"></span>
<span class="line">PRINT &quot;I am full!&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ستتحقق هذه الحلقة من الشرط (<code>hunger_level &gt; 0</code>). إذا كان صحيحًا، فإنها &quot;تأكل شريحة بيتزا&quot; وتقلل من مستوى الجوع. ستكرر هذا 5 مرات حتى يصل مستوى الجوع إلى 0، وعند هذه النقطة تتوقف الحلقة وتطبع &quot;I am full!&quot;.</p><p>الحلقات أدوات قوية بشكل لا يصدق ستستخدمها طوال الوقت أثناء بناء الخوارزميات!</p>`,24)])])}const c=n(l,[["render",d]]),o=JSON.parse('{"path":"/ar/loops.html","title":"الحلقات: تكرار المهام تلقائيًا","lang":"ar-MA","frontmatter":{},"headers":[{"level":2,"title":"لماذا نحتاج إلى الحلقات؟","slug":"لماذا-نحتاج-إلى-الحلقات؟","link":"#لماذا-نحتاج-إلى-الحلقات؟","children":[]},{"level":2,"title":"حلقة FOR","slug":"حلقة-for","link":"#حلقة-for","children":[{"level":3,"title":"تفصيل حلقة FOR","slug":"تفصيل-حلقة-for","link":"#تفصيل-حلقة-for","children":[]},{"level":3,"title":"مثال من العالم الواقعي","slug":"مثال-من-العالم-الواقعي","link":"#مثال-من-العالم-الواقعي","children":[]}]},{"level":2,"title":"حلقة WHILE","slug":"حلقة-while","link":"#حلقة-while","children":[]}],"git":{"updatedTime":1778106929000,"contributors":[{"name":"Aymane Benhima","username":"","email":"aymanebenhima.gmail.com","commits":2}],"changelog":[{"hash":"02c5b3cc51f9da680f9ea7a50ccdf218e1fb7b68","time":1778106929000,"email":"aymanebenhima.gmail.com","author":"Aymane Benhima","message":"feat: add multilingual documentation for variables, conditionals, and loops"},{"hash":"d0ac587de5ea00d050dbb9b4ba983301d2e58cae","time":1778105142000,"email":"aymanebenhima.gmail.com","author":"Aymane Benhima","message":"feat: initialize project with VuePress and multilingual documentation for JS fundamentals"}]},"filePathRelative":"ar/loops.md"}');export{c as comp,o as data};
